package com.sistema.sistema.infrastructure.persistence.inventorycount;
import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="inventory_count_items") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class InventoryCountItemEntity { @Id @GeneratedValue(strategy=GenerationType.SEQUENCE,generator="inventory_count_items_seq") @SequenceGenerator(name="inventory_count_items_seq",sequenceName="inventory_count_items_seq",allocationSize=1) private Long id; @Column(name="session_id") private Long sessionId; @Column(name="product_id") private Long productId; @Column(name="opening_stock") private Long openingStock; @Column(name="expected_stock") private Long expectedStock; @Column(name="physical_stock") private Long physicalStock; private Long difference; @Column(name="result_status") private String resultStatus; @Column(name="difference_reason") private String differenceReason; @Column(name="difference_comment") private String differenceComment; @Column(name="adjustment_status") private String adjustmentStatus; @Column(name="adjustment_movement_id") private Long adjustmentMovementId; @Column(name="counted_by") private Long countedBy; @Column(name="counted_at") private LocalDateTime countedAt; @Column(name="approved_by") private Long approvedBy; @Column(name="approved_at") private LocalDateTime approvedAt; }
